def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]
    opp = []
    opp_def = 0
    for a, b in history:
        opp.append(b)
        if b == 'D':
            opp_def += 1

    if n >= 10:
        tail = tuple(opp[-10:])
        if tail == ('D', 'D', 'C', 'C', 'C', 'D', 'D', 'C', 'C', 'C'):
            return 'D'

    if opp_def == 0:
        if n >= 80:
            return 'D'
        return 'C'

    if last_opp == 'C':
        return 'C'

    run = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        run += 1
        i -= 1

    prior_coop = 0
    for j in range(i + 1):
        if opp[j] == 'C':
            prior_coop += 1

    start = 0 if n < 10 else n - 10
    recent_d = 0
    for j in range(start, n):
        if opp[j] == 'D':
            recent_d += 1

    if (run >= 5 or recent_d >= 7 or
        opp_def > max(6, (2 * n) // 5) or
        (prior_coop < 5 and run >= 2)):
        return 'D'

    if run == 1:
        return 'C'

    if run == 2:
        return 'D'

    if last_me == 'D':
        return 'C'

    if run <= 3 and prior_coop >= 10 and opp_def <= 3:
        return 'C'

    return 'D'
